Q: Can we use firebase with flutter just for authentication and custom server for everything else? A: <pre><code>import 'package:firebase_auth/firebase_auth.dart';
import 'package:google_sign_in/google_sign_in.dart' show GoogleSignIn;

class AuthService{
  final FirebaseAuth _auth = FirebaseAuth.instance;
  final GoogleSignIn _googleSignIn = GoogleSignIn();

  User? get currentUser =&gt; _auth.currentUser;
  Stream&lt;User?&gt; get authStateChanges =&gt; _auth.authStateChanges();


  Future&lt;String?&gt; signUp(String email, String  password ) async{
    try{
      await _auth.createUserWithEmailAndPassword(email: email, password: password);
      return null;
    } on FirebaseAuthException catch(e){

      if(e.code == &quot;user-not-found&quot;){
        return &quot;No user found for that email&quot;;

      }else if(e.code == &quot;wrong-password&quot;){
        return &quot;Wrong password provided for that user&quot;;
      }else if(e.code == &quot;invalid-email&quot;){
        return &quot;Invalid email&quot;;
      }else if(e.code == &quot;email-already-in-use&quot;){
        return &quot;Email already in use&quot;;
      }else if(e.code == &quot;weak-password&quot;){
        return &quot;Weak password&quot;;
      }
      return e.message;

    }
  }

  Future&lt;String?&gt; signIn(String email, String  password ) async{
    try{
      await _auth.signInWithEmailAndPassword(email: email, password: password);
      return null;
    } on FirebaseAuthException catch(e){
      if(e.code == &quot;user-not-found&quot;){
        return &quot;No user found for that email&quot;;

      }else if(e.code == &quot;wrong-password&quot;){
        return &quot;Wrong password provided for that user&quot;;
      }else if(e.code == &quot;invalid-email&quot;){
        return &quot;Invalid email&quot;;
      }else if(e.code == &quot;email-already-in-use&quot;){
        return &quot;Email already in use&quot;;
      }else if(e.code == &quot;weak-password&quot;){
        return &quot;Weak password&quot;;
      }
      return e.message;

    }

  }

  Future&lt;void&gt; signOut() async{
    await _auth.signOut();
    await _googleSignIn.signOut();

  }





}import 'package:firebase1/service/auth_service.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

import 'auth.state.dart';

class AuthCubit extends Cubit&lt;AuthState&gt;{
  final AuthService _authService;

  AuthCubit(this._authService) : super(AuthInitial());

  Future&lt;void&gt; signIn(String email, String password) async{
    emit(AuthLoading());
    final error = await _authService.signIn(email, password);
      if(error == null){
      emit(AuthSuccess());
    }else{
      emit(AuthError(error));
    }
  }

  Future&lt;void&gt; signUp(String email, String password) async{
    emit(AuthLoading());
    final error = await _authService.signUp(email, password);
      if(error == null) {
        emit(AuthSuccess());
      }else{
        emit(AuthError(error));

      }
  }

  Future&lt;void&gt; signOut() async{
    await _authService.signOut();
    emit(AuthLoggedOut());
  }


}  void dispose() {
    _emailController.dispose();
    _passwordController.dispose();
    super.dispose();
  }

  void _showError(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message), backgroundColor: Colors.red),
    );
  }

  void _login() {
    if (_emailController.text.isEmpty || _passwordController.text.isEmpty) {
      _showError('Please fill all fields');
      return;
    }

    // ✅ Call Cubit method — NO async/await here in UI
    context.read&lt;AuthCubit&gt;().signIn(
      _emailController.text.trim(),
      _passwordController.text.trim(),
    );
  }
</code></pre>
